// TestRegisterAllSkipsHiddenAndFrameworkCommands proves the Cobra-tree
// mirror only emits novel user-facing commands. Commands hidden by Cobra,
// commands hidden by the mcp:hidden annotation, and top-level framework
// commands such as `search` must not become shell-out tools; otherwise they
// can leak private/control-plane commands or overwrite better typed MCP
// tools in the full server registration.
func TestRegisterAllSkipsHiddenAndFrameworkCommands(t *testing.T) {
	root := &cobra.Command{Use: "readwise-pp-cli"}
	root.AddCommand(
		runnableCommand("visible"),
		runnableCommand("search"),
		&cobra.Command{
			Use:    "cobra-hidden",
			Hidden: true,
			Run:    func(*cobra.Command, []string) {},
		},
		&cobra.Command{
			Use: "mcp-hidden",
			Annotations: map[string]string{
				HiddenAnnotation: "true",
			},
			Run: func(*cobra.Command, []string) {},
		},
	)

	s := server.NewMCPServer("test", "test", server.WithToolCapabilities(false))
	s.AddTool(mcplib.NewTool("search"), nil)
	RegisterAll(s, root, func() (string, error) { return "/unused/readwise-pp-cli", nil })

	tools := s.ListTools()
	if len(tools) != 2 {
		t.Fatalf("expected typed search and visible mirror, got %v", surfaceToolNames(tools))
	}
	if _, ok := tools["visible"]; !ok {
		t.Fatalf("visible command was not emitted as a shell-out tool; tools = %v", surfaceToolNames(tools))
	}
	for _, hidden := range []string{"cobra_hidden", "mcp_hidden"} {
		if _, ok := tools[hidden]; ok {
			t.Fatalf("command %q leaked into shell-out MCP tools; tools = %v", hidden, surfaceToolNames(tools))
		}
	}
}

func runnableCommand(use string) *cobra.Command {
	return &cobra.Command{
		Use: use,
		Run: func(*cobra.Command, []string) {},
	}
}

func surfaceToolNames(tools map[string]*server.ServerTool) []string {
	names := make([]string, 0, len(tools))
	for name := range tools {
		names = append(names, name)
	}
	return names
}
